package com.streamcraft.core.runtime;
import com.streamcraft.core.model.DataEntity; import com.streamcraft.core.model.PipelineNode; import com.streamcraft.shared.influxdb.InfluxDbSourceConfig; import com.streamcraft.shared.influxdb.InfluxDbSourceConfigParser; import org.apache.flink.api.common.eventtime.WatermarkStrategy; import org.apache.flink.streaming.api.datastream.DataStream; import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
public class InfluxDbSourceFactory { public DataStream<DataEntity> create(StreamExecutionEnvironment env,PipelineNode node){InfluxDbSourceConfig c=InfluxDbSourceConfigParser.parse(node.config(),IllegalArgumentException::new);int p=!c.splitMeasurements().isEmpty()?c.splitMeasurements().size():(c.splitEnabled()?c.splitCount():1);if(p>1)return env.fromSource(new InfluxDbSource(c),WatermarkStrategy.noWatermarks(),node.name()).setParallelism(p);return env.fromSource(new InfluxDbSource(c),WatermarkStrategy.noWatermarks(),node.name()).setParallelism(1);} }
